 out={'status':'source-bound-review-with-required-dispositions','candidateArtifactSHA256':sha(a.stage/'candidates.json'),'finiteReviewSHA256':sha(a.review),'reviewCodeSHA256':sha(Path(__file__)),'groups':groups,'humanReviewed':False,'formalProof':False,'disclosure':'Stage07 sample answer values were visible from parent before independent derivation. Replacement AGM/partition first solves were statement/options-first and separately recorded.','limits':'No source code or candidate was edited. Parent owns canonical admission, final source rebinding, global grouping and practice-horizon tests.'};dest=a.review.with_name('editorial-and-options-review.json');dest.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'groups':len(groups),'replicatedFlags':[(g['familyId'],[(q['feature'],q['mode']) for q in g['replicated65PercentRules']]) for g in groups if g['replicated65PercentRules']]}))
